<?php require dirname(__DIR__).'/config/config.php'; require dirname(__DIR__).'/vendor/autoload.php'; use App\Helpers\Security; use App\Helpers\Audit; Security::requireRole(['administrador','gerente']); if($_SERVER['REQUEST_METHOD']==='POST'){Security::checkCsrf($_POST['csrf']??null);$s=db()->prepare('INSERT INTO fornecedores(razao_social,cnpj,telefone,email,servico) VALUES(?,?,?,?,?)');$s->execute([trim($_POST['razao_social']),preg_replace('/\D/','',$_POST['cnpj']??''),trim($_POST['telefone']),filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL)?:null,trim($_POST['servico'])]);Audit::log('Cadastro de fornecedor','fornecedores',(int)db()->lastInsertId());header('Location: fornecedores.php');exit;}$rows=db()->query('SELECT * FROM fornecedores ORDER BY razao_social')->fetchAll();?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fornecedores</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-4"><h1>Fornecedores</h1><a href="dashboard.php">← Dashboard</a><form method="post" class="row g-2 card p-3 my-4"><input type="hidden" name="csrf" value="<?=Security::csrf()?>"><div class="col-md-3"><input class="form-control" name="razao_social" placeholder="Razão social" required></div><div class="col-md-2"><input class="form-control" name="cnpj" placeholder="CNPJ"></div><div class="col-md-2"><input class="form-control" name="telefone" placeholder="Telefone"></div><div class="col-md-2"><input class="form-control" type="email" name="email" placeholder="E-mail"></div><div class="col-md-2"><input class="form-control" name="servico" placeholder="Serviço"></div><div class="col-md-1"><button class="btn btn-primary">Salvar</button></div></form><table class="table"><thead><tr><th>Razão social</th><th>CNPJ</th><th>Contato</th><th>Serviço</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=Security::e($r['razao_social'])?></td><td><?=Security::e($r['cnpj'])?></td><td><?=Security::e($r['telefone'])?></td><td><?=Security::e($r['servico'])?></td></tr><?php endforeach;?></tbody></table></div></body></html>
